EXAMPLES = [{'description': 'supply and demand curves for a market, with the equilibrium price and quantity marked', 'code': "q = np.linspace(0, 10, 200)\nplt.plot(q, 10 - 0.8 * q, label=r'$D$')\nplt.plot(q, 2 + 0.8 * q, label=r'$S$')\nplt.plot([5, 5], [0, 6], linestyle='--', color='red', linewidth=1)\nplt.plot([0, 5], [6, 6], linestyle='--', color='red', linewidth=1)\nplt.scatter([5], [6], color='red', zorder=5, label='Equilibrium')\nplt.xlabel(r'$Q$')\nplt.ylabel(r'$P$')\nplt.title('Market equilibrium')\nplt.xlim(0, 10)\nplt.ylim(0, 12)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'a price ceiling or maximum price set below equilibrium, showing the shortage it causes', 'code': "q = np.linspace(0, 10, 200)\nplt.plot(q, 10 - 0.8 * q, label=r'$D$')\nplt.plot(q, 2 + 0.8 * q, label=r'$S$')\nplt.axhline(4, color='red', label='Price ceiling')\nplt.plot([2.5, 7.5], [4, 4], color='orange', linewidth=4, label='Shortage')\nplt.scatter([2.5, 7.5], [4, 4], color='orange', zorder=5)\nplt.xlabel(r'$Q$')\nplt.ylabel(r'$P$')\nplt.title('Price ceiling')\nplt.xlim(0, 10)\nplt.ylim(0, 12)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'a price floor or minimum price set above equilibrium, showing the surplus it causes', 'code': "q = np.linspace(0, 10, 200)\nplt.plot(q, 10 - 0.8 * q, label=r'$D$')\nplt.plot(q, 2 + 0.8 * q, label=r'$S$')\nplt.axhline(8, color='red', label='Price floor')\nplt.plot([2.5, 7.5], [8, 8], color='orange', linewidth=4, label='Surplus')\nplt.scatter([2.5, 7.5], [8, 8], color='orange', zorder=5)\nplt.xlabel(r'$Q$')\nplt.ylabel(r'$P$')\nplt.title('Price floor')\nplt.xlim(0, 10)\nplt.ylim(0, 12)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'an increase in demand shifting the demand curve right, with the old and new equilibrium both marked', 'code': "q = np.linspace(0, 10, 200)\nplt.plot(q, 10 - 0.8 * q, label=r'$D$')\nplt.plot(q, 12 - 0.8 * q, linestyle='--', label=r'$D_1$')\nplt.plot(q, 2 + 0.8 * q, label=r'$S$')\nplt.scatter([5], [6], color='grey', zorder=5, label='Old equilibrium')\nplt.scatter([6.25], [7], color='red', zorder=5, label='New equilibrium')\nplt.xlabel(r'$Q$')\nplt.ylabel(r'$P$')\nplt.title('Demand shifts right')\nplt.xlim(0, 10)\nplt.ylim(0, 12)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'a labour market with a minimum wage set above the equilibrium wage, showing the unemployment it causes', 'code': "l = np.linspace(0, 10, 200)\nplt.plot(l, 10 - 0.8 * l, label=r'$D_L$')\nplt.plot(l, 2 + 0.8 * l, label=r'$S_L$')\nplt.axhline(8, color='red', label='Minimum wage')\nplt.plot([2.5, 7.5], [8, 8], color='orange', linewidth=4, label='Unemployment')\nplt.scatter([2.5, 7.5], [8, 8], color='orange', zorder=5)\nplt.xlabel(r'$L$ (quantity of labour)')\nplt.ylabel(r'$W$ (wage)')\nplt.title('Minimum wage and unemployment')\nplt.xlim(0, 10)\nplt.ylim(0, 12)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'a break-even chart for a business, showing total revenue, total costs, fixed costs and the break-even point', 'code': "q = np.linspace(0, 80, 200)\nplt.plot(q, 10 * q, label='Total revenue')\nplt.plot(q, 200 + 5 * q, label='Total costs')\nplt.axhline(200, color='grey', linestyle=':', label='Fixed costs')\nplt.plot([40, 40], [0, 400], linestyle='--', color='red', linewidth=1)\nplt.scatter([40], [400], color='red', zorder=5, label='Break-even point')\nplt.xlabel('Output (units)')\nplt.ylabel('Value')\nplt.title('Break-even chart')\nplt.xlim(0, 80)\nplt.ylim(0, 800)\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}, {'description': 'a normal distribution curve with the upper five percent tail shaded, for a statistics significance test', 'code': "x = np.linspace(-4, 4, 400)\ny = np.exp(-x ** 2 / 2) / np.sqrt(2 * np.pi)\nplt.plot(x, y, label=r'$N(0, 1)$')\nplt.fill_between(x, y, where=(x >= 1.645), alpha=0.4, color='red', label='Upper 5%')\nplt.axvline(1.645, color='red', linestyle='--', linewidth=1)\nplt.xlabel(r'$z$')\nplt.ylabel('Density')\nplt.title('Standard normal distribution')\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.tight_layout()"}]